[3105] = { en = "Tainted Letter", tier = 1,
  t = "De besmette brief",
  d = "Ik moest je dit meteen geven als je terug was van de kampen van de kobolds, $N. Het lijkt een brief met het zegel van Drusilla. Zij is een van onze trainers hier. Ik zou niet wachten met lezen. Lees hem eerst, en doe dan pas andere dingen hier in de Abbey.",
  o = "Lees de Tainted Letter en praat met Drusilla La Salle naast Northshire Abbey.",
  p = "Ah, dus je bent er. Net op tijd, $N. Een paar wachters waren hier net. Ze keken me vreemd aan... zielige gewone mensen.",
  c = "Als je sterker wordt, word je verleid. Je moet jezelf altijd onder controle houden. Ik ga niet liegen: corruptie kan iedereen overkomen die magie gebruikt. Vooral iemand die met wezens uit de Twisting Nether werkt. Wees geduldig en wees voorzichtig... maar laat dat je ambitie niet tegenhouden.$B$BKom terug als je machtiger wordt. Dan leer ik je meer over onze gebruiken.",
  g = { {"besmette", "tainted (besmet)"}, {"zegel", "seal"}, {"kampen", "camps (kamp)"}, {"wachters", "guards (wachter)"}, {"zielige", "pathetic (zielig)"}, {"gewone", "ordinary, mundane (gewoon)"}, {"verleid", "tempted (verleiden)"}, {"onder controle", "under control"}, {"liegen", "to lie"}, {"overkomen", "to happen to"}, {"geduldig", "patient"}, {"voorzichtig", "careful, prudent"}, {"tegenhouden", "to hold back"}, {"machtiger", "more powerful (machtig)"}, {"gebruiken", "customs, ways (gebruik)"} },
},

[3115] = { en = "Tainted Memorandum", tier = 1,
  t = "Het besmette memorandum",
  d = "Je hielp me net. Toen kreeg ik dit memorandum voor jou. Lees het als je tijd hebt. Ik denk dat het van de heksenmeester-trainer Alamar komt. Kijk er even naar en zoek hem op in Anvilmar als je kunt.$B$BEn pas goed op jezelf, $N. Ze vertrouwen jouw soort hier niet zo.",
  o = "Lees de Tainted Memorandum en praat met Alamar Grimm in Anvilmar, boven Coldridge Valley.",
  p = "Geweldig! Je hebt mijn memorandum dus gekregen.$b$bLet niet op de dwazen om je heen, $N. Het Heilige Licht?! Het zwaard en het schild?! Dat zijn geen wegen voor ons. Wij hebben een open geest. Kijk wat 'gewone' magie met ons thuis heeft gedaan. Door die magie en die vervloekte knutselaars is ons volk bijna uitgestorven. En nu moeten we op de dwergen rekenen. Maar die werken liever samen met de mensen. Ons helpen om ons eigen thuis weer op te bouwen, doen ze niet. We zijn net tweederangs burgers. Heb je gezien hoe ze naar ons kijken?",
  c = "Maar dat maakt allemaal niet uit. Wat telt: je hebt je eigen Heilige Licht gezien! Je weet waar echte macht vandaan komt. Je begrijpt dat eigen bondgenoten veel... verstandiger zijn. Speciale bondgenoten. Bondgenoten die altijd gehoorzamen, wat de taak ook is. Tot hun laatste adem.$b$bEn daarvoor ben ik er, $N. Ik kan je de eerste stappen van die speciale krachten leren. Kom vaak bij me langs. Dan doe ik wat ik kan om je meer spreuken te leren.",
  g = { {"besmette", "tainted (besmet)"}, {"heksenmeester", "warlock"}, {"vertrouwen", "to trust"}, {"soort", "kind, sort"}, {"dwazen", "fools (dwaas)"}, {"geest", "mind"}, {"vervloekte", "damned, cursed (vervloekt)"}, {"knutselaars", "tinkerers (knutselaar)"}, {"uitgestorven", "extinct (uitsterven)"}, {"rekenen", "to rely (rekenen op)"}, {"tweederangs burgers", "second-class citizens"}, {"bondgenoten", "allies (bondgenoot)"}, {"verstandiger", "more prudent, wiser (verstandig)"}, {"gehoorzamen", "to obey"}, {"adem", "breath"}, {"spreuken", "spells (spreuk)"} },
},

[1598] = { en = "The Stolen Tome", tier = 1,
  t = "Het gestolen boek",
  d = "Jij daar! $n, toch?$b$bIk hoop dat je zeker weet dat je heksenmeester wilt worden. Want als je niet sterk genoeg bent, ga je waarschijnlijk ten onder.$b$bIk moet je les geven, maar eerst wil ik zeker weten dat je sterk genoeg bent.$b$bEr was een leerling in de Abbey. Hij is weggelopen om bij de Defias Brotherhood te gaan. Waarom het me iets kan schelen? Nou, hij heeft een paar belangrijke boeken gestolen.$b$bEen van die boeken wil ik zelf al heel lang hebben: de Powers of the Void. Steel het voor mij. Ze hebben het verstopt bij hun tent in de Vineyards.",
  o = "Haal de Powers of the Void op voor Drusilla La Salle.",
  p = "Ik kon het boek niet zelf stelen. Dat viel te veel op. Wat een geluk dat een van hun eigen sukkels het vuile werk voor me heeft gedaan.",
  c = "Uitstekend... Ik kon nooit bij dit boek komen. Het lag in een beveiligde vleugel van de bibliotheek. Als ik daar rondhing, was dat verdacht.$B$BNou, je hebt het goed gedaan. En ik geloof nu dat je je eigen imp waarschijnlijk wel aankunt. Dus ik heb geen reden om je niet te laten zien hoe je er een oproept.",
  g = { {"zeker weet", "are sure (zeker weten)"}, {"ten onder", "go under, be destroyed (ten onder gaan)"}, {"leerling", "student, novice"}, {"weggelopen", "ran away (weglopen)"}, {"schelen", "to care (het kan me schelen)"}, {"gestolen", "stolen (stelen)"}, {"Steel", "steal (stelen)"}, {"verstopt", "hidden (verstoppen)"}, {"viel te veel op", "stood out too much (opvallen)"}, {"sukkels", "dupes, suckers (sukkel)"}, {"vuile werk", "dirty work"}, {"Uitstekend", "excellent"}, {"beveiligde", "protected (beveiligd)"}, {"vleugel", "wing (of a building)"}, {"rondhing", "loitered (rondhangen)"}, {"verdacht", "suspicious"}, {"aankunt", "can handle (aankunnen)"}, {"oproept", "summon (oproepen)"} },
},

[1599] = { en = "Beginnings", tier = 1,
  t = "Het begin",
  d = "Jij moet de nieuwe heksenmeester zijn. Iedereen fluistert over je. Iemand mag je vast graag, want ze hebben me gevraagd om tijd vrij te maken van mijn onderzoek. Ik moet met je training beginnen.$b$bMaak je geen zorgen, ik neem het je niet kwalijk.$b$bDe makkelijkste oproepspreuk die je gaat leren, is die van de imp. Maar ik leer je die spreuk pas als je bewijst dat je de nodige magische en lichamelijke kracht hebt.$b$bBreng me drie feather charms van de frostmane novices uit de grot in het zuidwesten.",
  o = "Breng 3 Feather Charms naar Alamar Grimm in Anvilmar.",
  p = "Die feather charms van de novices hebben een soort magische kracht. Het wordt interessant om ze te onderzoeken. Dat had ik niet van de trollen verwacht.",
  c = "Heel goed, heel goed! Je hebt het goed gedaan, $N. Misschien verdien je de aandacht die je krijgt toch.$b$bDat moeten de anderen beslissen. Tenminste, als je imp jou niet de baas wordt en je carrière al aan het begin stopt. Voor nu ben ik tevreden. Je overleeft je eerste maanden als $C waarschijnlijk wel.$b$bNog iets over de imp, $N. Elke $R weet het: laat je niet misleiden door zijn grootte. Zijn magie kan heel gevaarlijk zijn.",
  g = { {"fluistert", "whispers (fluisteren)"}, {"vrij te maken", "to free up (vrijmaken)"}, {"onderzoek", "research"}, {"kwalijk", "against you (iemand iets kwalijk nemen)"}, {"oproepspreuk", "summoning spell"}, {"bewijst", "prove (bewijzen)"}, {"nodige", "necessary (nodig)"}, {"lichamelijke", "physical (lichamelijk)"}, {"grot", "cave"}, {"zuidwesten", "southwest"}, {"onderzoeken", "to research, to study"}, {"verdien", "deserve (verdienen)"}, {"aandacht", "attention"}, {"de baas wordt", "overpowers, gets the better of"}, {"overleeft", "survive (overleven)"}, {"misleiden", "to fool, to mislead"}, {"grootte", "size"} },
},

[1685] = { en = "Gakin's Summons", tier = 1,
  t = "Gakin roept je op",
  d = "Zo gaat het toch altijd? Ik zocht je de hele dag en kon je niet vinden. En nu ik het niet verwacht, kom je zomaar naar me toe.$b$bIk heb genoeg tijd verspild met zoeken, dus ik houd je niet langer op. Meester Gakin heeft je opgeroepen voor extra training. Volgens mij moet je hem zo snel mogelijk opzoeken.$b$bJe vindt hem in de kelder van de herberg de Slaughtered Lamb. Trouwens, je kunt die plek beter geheimhouden. We willen niet dat iedereen erover praat.",
  o = "Meld je bij Gakin the Darkbinder in de Mage Quarter van Stormwind.",
  c = "Werd tijd dat je kwam. Misschien had ik iemand slimmers moeten sturen dan Remen om je te vinden.$B$BMaakt niet uit.$B$BJe hebt te lang geen training gehad. En een heksenmeester zonder training houdt zijn hoofd niet lang op zijn schouders.",
  g = { {"zomaar", "just like that"}, {"verspild", "wasted (verspillen)"}, {"houd je niet langer op", "won't delay you any longer (ophouden)"}, {"opgeroepen", "summoned (oproepen)"}, {"opzoeken", "to look up, to seek out"}, {"kelder", "basement, cellar"}, {"herberg", "tavern, inn"}, {"Trouwens", "by the way"}, {"geheimhouden", "to keep secret"}, {"Meld je", "report (zich melden)"}, {"Werd tijd", "about time"}, {"slimmers", "more capable, cleverer (slim)"}, {"schouders", "shoulders (schouder)"} },
},

[1688] = { en = "Surena Caledon", tier = 1,
  t = "Surena Caledon",
  d = "Ik had een leerling, Surena Caledon. Ze stond waar jij nu staat. Ze wilde graag de magie van heksenmeesters leren, en ze had veel talent. Bovendien was ze jong en mooi om te zien. Had ik het toen maar gezien, die verraderlijke del!$b$bDie dievegge is ervandoor gegaan met een van de Defias, Erlan Drudgemoor. Haar verlies is niet belangrijk. Maar ik gaf haar een halsband van bloedsteen, en die moet ik terug hebben.$b$bHaar leven betekent nu niets meer voor me. Je vindt haar bij de Brackwell Pumpkin Patch. Haal terug wat van mij is.",
  o = "Haal Surena's Choker op voor Gakin the Darkbinder in Stormwind.",
  p = "Ook ouderen en wijzen kunnen zwak worden door de listen van jeugd en schoonheid, $N. Dat is goed advies. Onthoud het je hele leven.",
  c = "Surena had talent, maar niet genoeg om in haar eentje de magie van een $C te beheersen. Het is jammer als talent verspild wordt, maar soms is het nodig.$B$BIk hoop dat mijn investering in jou een ander resultaat oplevert.",
  g = { {"leerling", "student"}, {"Bovendien", "moreover, more than that"}, {"Had ik het toen maar gezien", "had I only seen it then"}, {"verraderlijke", "treacherous (verraderlijk)"}, {"del", "trollop, slut"}, {"dievegge", "thief (f.)"}, {"ervandoor gegaan", "ran off (ervandoor gaan)"}, {"verlies", "loss"}, {"halsband", "choker, collar"}, {"bloedsteen", "bloodstone"}, {"wijzen", "wise people (wijze)"}, {"listen", "wiles, tricks (list)"}, {"jeugd", "youth"}, {"schoonheid", "beauty"}, {"in haar eentje", "on her own"}, {"beheersen", "to master"}, {"investering", "investment"}, {"oplevert", "yields, produces (opleveren)"} },
},

[1689] = { en = "The Binding", tier = 1,
  t = "De binding",
  d = "Je hebt mijn halsband teruggehaald en Surena verslagen. Daarmee heb je laten zien dat je minstens zo goed bent als zij.$b$bMaar ik zie ook dat je dringend training nodig hebt. Je kunt de stromen van magie sturen, ja. Maar een heksenmeester zijn is veel meer dan dat.$b$bIk zal je leren hoe je een voidwalker beveelt. Maar eerst moet je er een oproepen bij een oproepcirkel. Dan moet je hem onderwerpen met alle wapens die je hebt, gewone en magische. Gebruik de magie van deze halsband bij de oproepcirkel hieronder.",
  o = "Roep met de Bloodstone Choker een voidwalker op en onderwerp hem. Breng daarna de Bloodstone Choker terug naar Gakin the Darkbinder in Stormwind.",
  p = "Ik kan je niet leren hoe je een voidwalker bestuurt, als je er nog geen hebt verslagen.",
  c = "Je deed het beter dan ik had verwacht, $N, maar wel zo goed als ik had gehoopt. Nu kun je leren je onderworpen voidwalker te bevelen. Het is een bondgenoot waar je veel aan hebt bij de beproevingen die zeker voor je liggen.$B$BIk heb je op dit moment niets meer te leren, maar ik ben nog lang niet klaar met jou, $N.",
  g = { {"binding", "binding"}, {"teruggehaald", "retrieved (terughalen)"}, {"verslagen", "defeated (verslaan)"}, {"minstens", "at least"}, {"dringend", "urgently"}, {"stromen", "flows (stroom)"}, {"beveelt", "command (bevelen)"}, {"oproepcirkel", "summoning circle"}, {"onderwerpen", "to subdue"}, {"hieronder", "below, down here"}, {"bestuurt", "control (besturen)"}, {"onderworpen", "subjugated (onderwerpen)"}, {"beproevingen", "trials (beproeving)"}, {"nog lang niet", "far from"} },
},

[1715] = { en = "The Slaughtered Lamb", tier = 1,
  t = "De Slaughtered Lamb",
  d = "Hmpf. Vroeger werden alle heksenmeesters in Khaz Modan opgeleid onder toezicht van de meesters van Gnomeregan. Maar nu moesten we allemaal verhuizen naar dit rattenhol in Ironforge. En Magni heeft besloten ons goed in de gaten te houden. Dus moeten we onze nieuwelingen naar Stormwind sturen voor hun training.$b$bGelukkig is Gakin goed in zijn vak, dus je leert nog steeds wat je moet weten. Maar ik word er razend van!$b$bHoe dan ook, je vindt Gakin in de kelder van de Slaughtered Lamb in Stormwind.",
  o = "Meld je bij Gakin the Darkbinder in de Mage Quarter van Stormwind.",
  c = "Dus Blackwrench heeft je gestuurd? Die vervloekte heksenmeesters in Ironforge moeten hun zaken eens regelen. Er is maar zoveel ruimte en er zijn maar zoveel leraren in Stormwind. Met al die extra drukte trekken we vroeg of laat zeker aandacht.",
  g = { {"opgeleid", "trained (opleiden)"}, {"onder toezicht", "under the supervision"}, {"verhuizen", "to move, to relocate"}, {"rattenhol", "rat's hole"}, {"in de gaten te houden", "to keep an eye on (in de gaten houden)"}, {"nieuwelingen", "novices (nieuweling)"}, {"vak", "trade, profession"}, {"razend", "furious"}, {"Hoe dan ook", "anyway"}, {"vervloekte", "damned (vervloekt)"}, {"zaken", "affairs, things (zaak)"}, {"regelen", "to sort out"}, {"drukte", "busyness, traffic"}, {"vroeg of laat", "sooner or later"}, {"aandacht", "attention"} },
},

[1716] = { en = "Devourer of Souls", tier = 1,
  t = "Verslinder van zielen",
  d = "Een succubus verslindt zielen, vernietigt harten en overheerst gedachten. Het kent alleen het kwaad.$b$bDit is het wezen dat je leert oproepen en beheersen. Maar je kunt het niet in onze wereld brengen zonder een prikkel.$b$bAls je een symbool van liefde als lokaas gebruikt, beantwoordt het zeker je roep. Dan kun je het verslaan en er je werktuig van maken.$b$bHet is wel moeilijk om zoiets te vinden. Praat met Takar the Seer. Je vindt hem in de Barrens van Kalimdor, bij Camp Taurajo.",
  o = "Praat met Takar the Seer in de Barrens.",
  c = "Was je overtocht zwaar, $N? Je bent van ver gekomen om met mij te praten. Maar wees niet bang. Ik weet waarom Gakin je heeft gestuurd, en dat was wijs van hem, want ik kan je helpen bij je zoektocht.",
  g = { {"Verslinder", "devourer"}, {"verslindt", "devours (verslinden)"}, {"zielen", "souls (ziel)"}, {"vernietigt", "destroys (vernietigen)"}, {"overheerst", "dominates (overheersen)"}, {"kwaad", "evil"}, {"beheersen", "to control"}, {"prikkel", "stimulus"}, {"lokaas", "bait"}, {"beantwoordt", "answers (beantwoorden)"}, {"roep", "call"}, {"werktuig", "tool, instrument"}, {"overtocht", "crossing"}, {"wijs", "wise"}, {"zoektocht", "search"} },
},

[1717] = { en = "Gakin's Summons", tier = 1,
  t = "Gakin roept je op",
  d = "$n! Ik had je hier niet verwacht, maar ik moest naar je uitkijken.$b$bHet is hoog tijd voor meer training. Ga dus bij Gakin langs als je weer in Stormwind bent. Hij wacht op je.",
  o = "Meld je bij Gakin the Darkbinder in de Mage Quarter van Stormwind.",
  c = "Ik ben blij dat iemand je kon bereiken, $n. Ik begon al het ergste te vrezen. Het zou zonde zijn om je te verliezen, na alle tijd die we in je hebben gestoken.$b$bWe praten later wel. Je training is nu het enige wat belangrijk is.",
  g = { {"verwacht", "expected (verwachten)"}, {"uitkijken", "to look out (for)"}, {"hoog tijd", "high time"}, {"langs", "by (langsgaan: to stop by)"}, {"bereiken", "to reach"}, {"het ergste", "the worst"}, {"vrezen", "to fear"}, {"zonde", "a shame, a pity"}, {"verliezen", "to lose"}, {"gestoken", "put in, invested (steken)"} },
},

[1738] = { en = "Heartswood", tier = 1,
  t = "Heartswood",
  d = "Ik heb me voorbereid op je komst. Ik heb met mijn zicht over de wereld gekeken, en door de nevels van de tijd. Ik heb gevonden wat je zoekt.$b$bIn de War of the Ancients vielen twee geliefden samen in de strijd. Ze bliezen hun laatste adem uit op één plek. Daar groeide een boom: de heartswood. Hij is een symbool van hun eeuwige liefde.$b$bDat moet genoeg zijn om een succubus te verleiden. Je vindt hem in de ruïnes van Ordil'Aran, in het noordwesten van het woud van Ashenvale.",
  o = "Haal de Heartswood uit Ashenvale en breng het naar Gakin the Darkbinder in de Mage Quarter van Stormwind.",
  p = "Was je zoektocht een succes, $N?",
  c = "Ja, ik zie al dat dit goed zal werken. Laat me er even mee werken...$B$BTakar is handig om in de buurt te hebben, hè? Kon ik hem maar overhalen om terug naar de beschaving te verhuizen.",
  g = { {"voorbereid", "prepared (voorbereiden)"}, {"komst", "coming, arrival"}, {"zicht", "sight"}, {"nevels", "mists (nevel)"}, {"geliefden", "lovers (geliefde)"}, {"strijd", "battle"}, {"bliezen hun laatste adem uit", "breathed their last (uitblazen)"}, {"eeuwige", "eternal, undying (eeuwig)"}, {"verleiden", "to tempt"}, {"ruïnes", "ruins (ruïne)"}, {"woud", "forest"}, {"handig", "handy, resourceful"}, {"Kon ik hem maar overhalen", "if only I could persuade him (overhalen)"}, {"beschaving", "civilization"} },
},

[1739] = { en = "The Binding", tier = 1,
  t = "De binding",
  d = "Met de kern van de heartswood kun je bij de oproepcirkel in de crypte hieronder een spreuk uitspreken. Die opent een portaal, en daardoor kan de succubus komen.$b$bWees voorzichtig, $n. Succubi hebben zelfs de sterkste geesten overmand.$b$bAls je het wezen hebt verslagen en teruggestuurd naar de leegte, kom dan terug bij mij. Dan leer ik je hoe je het oproept en beheerst.",
  o = "Roep met de Heartswood Core een succubus op en onderwerp hem. Breng daarna de Heartswood Core terug naar Gakin the Darkbinder in de Slaughtered Lamb.",
  p = "Soms vraag ik me af of Surena niet een vermomde succubus was. Gestuurd om mijn geest te verdraaien en te verwringen... Ha! Ik geef haar te veel eer, denk ik.",
  c = "Goed gedaan, goed gedaan, $N. Ik zie dat we de juiste keuze hebben gemaakt om je te trainen. Je prestatie stelt zeker niet teleur.$B$BIk heb er geen moeite mee om je te laten zien hoe je je nieuwe gebonden succubus beheerst. Kijk goed.",
  g = { {"kern", "core"}, {"crypte", "crypt"}, {"uitspreken", "to cast (a spell), to pronounce"}, {"portaal", "portal"}, {"geesten", "minds (geest)"}, {"overmand", "overwhelmed (overmannen)"}, {"leegte", "void, emptiness"}, {"vermomde", "disguised (vermomd)"}, {"verdraaien", "to twist"}, {"verwringen", "to warp, to distort"}, {"eer", "credit, honour"}, {"prestatie", "performance"}, {"stelt zeker niet teleur", "certainly does not disappoint (teleurstellen)"}, {"moeite", "trouble, qualms"}, {"gebonden", "bound (binden)"} },
},

[1758] = { en = "Tome of the Cabal", tier = 2,
  t = "Tome of the Cabal",
  d = "Er is meer nodig dan een simpele oproepcirkel om een felhunter op te roepen die je kunt uitdagen.$b$bMijn drie acolieten en ik zullen helpen om de magische cirkels te maken. Je hebt een exemplaar van de Tome of the Cabal nodig, maar dat zijn we al een tijd kwijt. Het is geschreven door de eerste groep heksenmeesters die zonder hulp een felhunter opriep.$b$bMisschien kan Krom Stoutarm je hiermee helpen. Hij is tegenwoordig een rondtrekkende heksenmeester. Hij brengt zijn dagen door met het oppotten van oude teksten en het rondsluipen in de bibliotheek van Ironforge.",
  o = "Praat met Krom Stoutarm in Ironforge.",
  c = "Tome of Cabal? Hmm... dat klinkt bekend. Maar ik heb het hier nog nooit gezien. En geloof me, ik onthoud elk boek dat ik lees.$B$BHmm... Ah, ja!$B$BIk heb er een verwijzing naar gezien in de catalogusboeken van de bibliotheek.",
  g = { {"uitdagen", "to challenge"}, {"acolieten", "acolytes (acoliet)"}, {"exemplaar", "copy"}, {"kwijt", "lost"}, {"zonder hulp", "unaided"}, {"opriep", "summoned (oproepen)"}, {"tegenwoordig", "these days"}, {"rondtrekkende", "itinerant, wandering (rondtrekken)"}, {"oppotten", "hoarding"}, {"rondsluipen", "skulking about"}, {"bekend", "familiar"}, {"onthoud", "remember (onthouden)"}, {"verwijzing", "reference"}, {"catalogusboeken", "cataloguing books"} },
},

[1795] = { en = "The Binding", tier = 2,
  t = "De binding",
  d = "Als je goed genoeg voorbereid bent, dan moeten we beginnen. Ik zal je uitleggen hoe het werkt.$b$bEerst maak ik de gewone oproepcirkel. Als die klaar is, gebruiken mijn acolieten de rods of channeling om de grote cirkel te maken.$b$bAls dat gedaan is, lees je de bezwering voor uit de Tome of the Cabal, en dan wordt de felhunter naar voren getrokken. Wees voorzichtig, $n. Een felhunter is een sterke vijand, en ik zie graag dat je je hoofd op je schouders houdt.",
  o = "Roep met de Tome of the Cabal een felhunter op en onderwerp hem. Breng daarna de Tome of the Cabal terug naar Strahad Farsan in Ratchet.",
  p = "Elke $C hoort een felhunter onder bevel te hebben. Het is moeilijk om er een te temmen, maar de krachten die hij aan zijn meester geeft, zijn veel meer waard dan wat het kost.",
  c = "Ik moet zeggen dat ik onder de indruk ben, $N. Toen ik tegenover mijn felhunter stond, ontsnapte ik maar net met mijn leven. Ik voel dat je de aanleg hebt om een van de machtigste heksenmeesters van deze tijd te worden.",
  g = { {"voorbereid", "prepared (voorbereiden)"}, {"uitleggen", "to explain"}, {"acolieten", "acolytes (acoliet)"}, {"bezwering", "incantation"}, {"lees je de bezwering voor", "you read out the incantation (voorlezen)"}, {"naar voren getrokken", "pulled forth"}, {"vijand", "foe, enemy"}, {"onder bevel", "under command"}, {"temmen", "to tame"}, {"meer waard", "worth more"}, {"onder de indruk", "impressed"}, {"ontsnapte", "escaped (ontsnappen)"}, {"maar net", "barely"}, {"aanleg", "potential, talent"}, {"machtigste", "most powerful (machtig)"} },
},

[1798] = { en = "Seeking Strahad", tier = 2,
  t = "Op zoek naar Strahad",
  d = "Het is tijd dat je leert hoe je een felhunter oproept, $n. Ik heb hier niet de reagentia en voorwerpen die ik nodig heb om het je te leren. Je moet dus iemand anders opzoeken: Strahad Farsan, nog een lid van onze binnenste kring.$b$bHij woont in de goblinhaven Ratchet. Ik stuur hem vooraf bericht dat je komt.",
  o = "Praat met Strahad Farsan in de Barrens.",
  c = "$N? Ah, natuurlijk. Ons nieuwste wonderkind. De werkelijkheid is nooit zo goed als de legende, ben ik bang.$B$BMaakt niet uit. Je bent hier gekomen om te leren, niet om mij grapjes tegen mezelf te horen maken.",
  g = { {"reagentia", "reagents (reagens)"}, {"voorwerpen", "items, objects (voorwerp)"}, {"opzoeken", "to seek out"}, {"lid", "member"}, {"binnenste kring", "inner circle"}, {"goblinhaven", "goblin port"}, {"vooraf", "ahead, in advance"}, {"bericht", "message, word"}, {"nieuwste", "latest, newest (nieuw)"}, {"wonderkind", "prodigy"}, {"werkelijkheid", "reality, the real thing"}, {"legende", "legend"}, {"ben ik bang", "I'm afraid"}, {"grapjes", "jokes (grapje)"} },
},

[1802] = { en = "Tome of the Cabal", tier = 2,
  t = "Tome of the Cabal",
  d = "Het is verloren gegaan, maar we hebben wel een idee waar het misschien te vinden is.$b$bEr is maar één exemplaar ooit gemaakt, en dat is op een gegeven moment vernield. Een groot deel is uit de band gescheurd. Volgens de geruchten is het op de een of andere manier in handen gekomen van de centaurs van Thousand Needles.$b$bDe rest is verloren gegaan voor de kust ten westen van Southshore. Het zou per boot naar Menethil Harbor gebracht worden, maar het is daar nooit aangekomen.$b$bIn ruil voor deze kennis vraag ik alleen dit: als je het vindt, breng het dan bij mij zodat ik het kan zien.",
  o = "Haal de Moldy Tome en Tattered Manuscript op voor Krom Stoutarm in Ironforge.",
  p = "Waren de geruchten waar, $N?",
  c = "Fantastisch! Nu hoor ik bij de weinigen die de inhoud hebben gezien.$B$BIk kan niet wachten om deze tekst verder te bestuderen. Dit is een geweldige dag, $N! Laat me er alsjeblieft even naar kijken voordat je gaat. Ik weet zeker dat Strahad me wel een kopie wil sturen.",
  g = { {"verloren gegaan", "lost (verloren gaan)"}, {"exemplaar", "copy"}, {"op een gegeven moment", "at some point"}, {"vernield", "vandalized, destroyed (vernielen)"}, {"band", "binding (of a book)"}, {"gescheurd", "ripped (scheuren)"}, {"geruchten", "rumours (gerucht)"}, {"op de een of andere manier", "somehow"}, {"kust", "coast"}, {"ten westen van", "west of"}, {"In ruil voor", "in exchange for"}, {"kennis", "knowledge"}, {"inhoud", "contents"}, {"bestuderen", "to study, to peruse"} },
},

[1804] = { en = "Tome of the Cabal", tier = 2,
  t = "Tome of the Cabal",
  d = "Nou, eh, het is moeilijk om het los te laten. Maar jij hebt het gevonden, en jij hebt er natuurlijk belangrijkere dingen mee te doen. Maar zeg alsjeblieft tegen Strahad dat ik een kopie wilde.$b$bToen je weg was, heeft hij een bericht voor je gestuurd. Hij wil dat zijn acolieten helpen bij het oproepen. Daarvoor moet je drie rods of channeling halen.$b$bHij weet misschien niet waar je ze kunt vinden, maar ik wel! Ze werden het laatst gebruikt door de orcs van de Dragonmaw-clan in de Wetlands. Ik zou bij hun spreukenwerpers kijken!",
  o = "Breng de Reconstructed Tome en 3 Rods of Channeling naar Strahad Farsan in Ratchet.",
  p = "Ik heb je hier al een tijdje niet gezien. Heb je het boek en de staven gevonden?",
  c = "Goed gedaan! De Tome of the Cabal en drie gave rods of channeling. Nou ja, een beetje bekrast, denk ik.$B$BDit wordt interessant. Het is alweer een tijd geleden dat een jonge $C een felhunter bevocht om hem voor zichzelf te nemen.",
  g = { {"los te laten", "to let go (loslaten)"}, {"belangrijkere", "more important (belangrijk)"}, {"bericht", "message"}, {"acolieten", "acolytes (acoliet)"}, {"halen", "to get, to fetch"}, {"het laatst", "last"}, {"spreukenwerpers", "spellcasters (spreukenwerper)"}, {"een tijdje", "a while"}, {"staven", "rods (staf)"}, {"gave", "pristine, intact (gaaf)"}, {"bekrast", "scratched (bekrassen)"}, {"alweer", "already (again)"}, {"bevocht", "took on, fought (bevechten)"}, {"zichzelf", "himself, themselves"} },
},

[1796] = { en = "Components for the Enchanted Gold Bloodrobe", tier = 2,
  t = "Onderdelen voor de Enchanted Gold Bloodrobe",
  d = "Het eerste voorwerp dat ik je help maken, is een gewaad. Jij verzamelt de spullen voor me, en wij zetten ze samen in elkaar. Daarna heb je, als het je lukt, het eerste van vele voorwerpen die je machtiger maken en je helpen in je strijd.$B$BOm te beginnen moet je Robes of Arcana hebben die gemaakt zijn. Een kleermaker kan die voor je maken, of misschien kun je ze van iemand anders kopen. Ik zou het heel knap vinden als je ze zelf kon maken. Maar hoe dan ook: breng me het gewaad, en dan gaan we verder.",
  o = "Breng Robes of the Arcana naar Menara Voidrender in de Barrens.",
  p = "Hoe gaat je zoektocht naar het gewaad, $N? Heb je het zelf gemaakt? Zulke persoonlijke details maken het doordrenken met magie voor mij des te zoeter. Het geeft je een groter gevoel van voldoening. Maar ik begrijp het als je de snellere weg kiest en het voor je laat maken. Er valt veel te zeggen voor zulke... ambitie.",
  c = "Dit is prima, $N.$B$BElk magisch voorwerp moet beginnen met een voorwerp van hoge kwaliteit. Hoe meer moeite en vakmanschap erin zit, hoe meer magie het kan bevatten. Zeldzame en duurdere onderdelen houden de magie beter vast. Je zult er geen spijt van krijgen dat dit gewaad later wordt omgevormd tot het gewaad dat we voor je maken.",
  g = { {"Onderdelen", "components (onderdeel)"}, {"gewaad", "robe"}, {"in elkaar", "together (in elkaar zetten: to assemble)"}, {"machtiger", "more powerful (machtig)"}, {"strijd", "struggle"}, {"kleermaker", "tailor"}, {"knap", "impressive, clever"}, {"hoe dan ook", "regardless, anyway"}, {"persoonlijke", "personal (persoonlijk)"}, {"doordrenken", "imbuing, soaking"}, {"des te zoeter", "all the sweeter"}, {"voldoening", "satisfaction, accomplishment"}, {"vakmanschap", "craftsmanship, skill"}, {"bevatten", "to hold, to contain"}, {"spijt", "regret"}, {"omgevormd", "transformed, fashioned (omvormen)"} },
},

[4738] = { en = "In Search of Menara Voidrender", tier = 2,
  t = "Op zoek naar Menara Voidrender",
  d = "Laten we één ding duidelijk maken, $N: ik vind niet dat je klaar bent voor zulke verantwoordelijkheden. Ik vind dat een beginner nooit moet helpen bij het maken van een voorwerp van macht. Zeker niet iemand die nog zo weinig getest is.$B$BMaar dat is niet aan mij. De machten die er zijn, of in elk geval degenen die zulke geschenken aan je willen geven, mogen dat beslissen.$B$BAls je meer wilt leren, zoek dan Menara Voidrender op in Ratchet. Ze woont meestal in de toren boven het havenstadje.",
  o = "Praat met Menara Voidrender in de Barrens.",
  c = "Ah, Demisette heeft je gestuurd. Goed. Dan komt het nieuws dus ver genoeg om toekomstige leerlingen te vinden. Daar ben ik blij om.$B$BHet is typisch voor ons soort, $N, om samen te werken, welk ras we ook hebben. Dat is extra belangrijk, want de wezens met wie we het meest te maken hebben, maken geen onderscheid in hun kwaadaardigheid als we ze niet tevredenstellen of niet goed beheersen.$B$BIk vind dat je veel hebt geleerd. Als je wilt, help ik je om hulpmiddelen te maken die je vaardigheden aanvullen.",
  g = { {"duidelijk", "clear"}, {"verantwoordelijkheden", "responsibilities (verantwoordelijkheid)"}, {"beginner", "novice"}, {"getest", "tested (testen)"}, {"dat is niet aan mij", "that's not my decision"}, {"in elk geval", "at least, in any case"}, {"degenen", "those (people)"}, {"geschenken", "gifts (geschenk)"}, {"havenstadje", "little port town"}, {"toekomstige", "future (toekomstig)"}, {"typisch", "typical"}, {"onderscheid", "distinction, discrimination"}, {"kwaadaardigheid", "malice"}, {"tevredenstellen", "to appease, to satisfy"}, {"hulpmiddelen", "tools (hulpmiddel)"}, {"vaardigheden", "skills (vaardigheid)"}, {"aanvullen", "to complement"} },
},

[1949] = { en = "Hidden Secrets", tier = 3,
  t = "Verborgen geheimen",
  d = "Om je toverstok te maken, moet ik belangrijke passages lezen uit een bepaald boek. Het boek heet Rituals of Power en is geschreven door Magus Tirth.$B$BIk heb geen exemplaar van zijn boek, en geen van de grote bibliotheken van de wereld heeft het. Dus je moet met Tirth praten en het van hem krijgen.$B$BSucces. Tirth was vroeger een groot magiër en geleerde, maar nu brengt hij zijn tijd door bij de races van de gnomen en goblins in de Shimmering Flats, waar hij drinkt en gokt.",
  o = "Praat met Magus Tirth in de Shimmering Flats.",
  c = "Wat? Praat harder! Deze oude oren zijn niet meer zo scherp als vroeger.$B$BNou, ik hoop dat je hier bent met een verse pul bier of een paar goede tips voor de volgende race! Zo niet, dan kun je beter doorlopen... want ik heb een polymorph-toverstok met jouw naam erop!",
  g = { {"toverstok", "wand"}, {"passages", "passages (of a text)"}, {"bepaald", "certain, particular"}, {"exemplaar", "copy (of a book)"}, {"geleerde", "scholar"}, {"brengt hij zijn tijd door", "he spends his time (doorbrengen)"}, {"gokt", "gambles (gokken)"}, {"harder", "louder"}, {"scherp", "sharp"}, {"pul", "mug, tankard"}, {"doorlopen", "to keep walking"} },
},

[1948] = { en = "Items of Power", tier = 3,
  t = "Voorwerpen van macht",
  d = "Het maken van een toverstok voor een magiër is niet makkelijk. Er zijn zeldzame stoffen nodig, en er moet een vat gemaakt worden dat grote hoeveelheden magische energie kan opslaan. Je moet deze dingen verzamelen en naar mij brengen.$B$BIk heb op dit perkament geschreven wat je nodig hebt, en hoe je het kunt krijgen. Breng me precies wat op deze lijst staat, en volg mijn geschreven aanwijzingen tot op de letter. Want als je dat niet doet, dan kan het maken van je toverstok... slecht aflopen.",
  o = "Breng 1 Jade en de Bolt Charged Bramble naar Tabetha in Dustwallow Marsh.",
  p = "Hallo, $N. Heb je de spullen die ik nodig heb?",
  c = "Aha! Je hebt de jade en je hebt de braamtak gemaakt! Goed gedaan!$B$BIs dat rook die ik uit je oren zie komen? Misschien kwam je te dicht bij de totemstokken toen de bliksem insloeg, maar maak je geen zorgen. Door de bliksem geraakt worden brengt geluk!",
  g = { {"zeldzame", "rare (zeldzaam)"}, {"stoffen", "substances (stof)"}, {"vat", "vessel, container"}, {"hoeveelheden", "quantities (hoeveelheid)"}, {"opslaan", "to store"}, {"perkament", "parchment"}, {"aanwijzingen", "instructions (aanwijzing)"}, {"tot op de letter", "to the letter"}, {"aflopen", "to turn out, to end"}, {"braamtak", "bramble branch"}, {"rook", "smoke"}, {"bliksem", "lightning"}, {"insloeg", "struck (inslaan)"}, {"geraakt", "hit (raken)"} },
},

[1951] = { en = "Rituals of Power", tier = 3,
  t = "Rituals of Power",
  d = "Hm... nu ik erover nadenk, ik heb mijn boek niet! Weet je, ik had wat gokschulden, en om die af te betalen heb ik het laatste exemplaar van Rituals of Power verkocht aan een geestelijke....$B$BEen lid van de Scarlet Brotherhood. Hij heeft het vast meegenomen naar hun bibliotheek in het Scarlet Monastery in Tirisfal Glades!$B$BAls je dat boek wilt, dan moet je naar het klooster gaan om het te vinden. En sorry voor alle moeite. Ik ben mezelf niet de laatste tijd...",
  o = "Breng het boek Rituals of Power naar Tabetha in Dustwallow Marsh.",
  p = "Gegroet, $N. Heb je het boek Rituals of Power gevonden?",
  c = "Dat is het! Het is precies wat ik nodig heb om het ritueel voor te bereiden waarmee ik je toverstok maak! Ik hoop dat het niet te veel moeite was om het te vinden...",
  g = { {"nu ik erover nadenk", "now that I think about it"}, {"gokschulden", "gambling debts (gokschuld)"}, {"af te betalen", "to pay off (afbetalen)"}, {"exemplaar", "copy (of a book)"}, {"geestelijke", "clergyman, member of the clergy"}, {"lid", "member"}, {"klooster", "monastery"}, {"moeite", "trouble, effort"}, {"Ik ben mezelf niet", "I'm not myself"}, {"ritueel", "ritual"}, {"voor te bereiden", "to prepare (voorbereiden)"} },
},

