[1957] = { en = "Mana Surges", tier = 3,
  t = "Uitbarstingen van mana",
  d = "We zijn bijna klaar, maar deze laatste stap is de gevaarlijkste, $N.$B$BIk heb de lege bol van de oproeper en ik ben klaar om hem kracht te geven. Dat doen we door de energie van een manascheur te benutten. Ik spreek een spreuk uit die voor korte tijd een scheur opent. Daaruit zullen wezens stromen: mana surges. Je moet de mana surges verslaan, dan komt hun kracht vrij, en die verzamel ik dan.$B$BDood genoeg mana surges voordat de scheur sluit, en ik stop al hun verzamelde energie in je bol.",
  o = "Dood 12 Mana Surges binnen de toegestane tijd.",
  p = "Je hebt nog niet genoeg mana surges gedood, $N.",
  c = "Het is je gelukt! Ik heb geen seconde aan je getwijfeld! Oké, misschien heel even, één of twee seconden... maar eigenlijk twijfelde ik nauwelijks.$B$BEerlijk waar.",
  g = { {"Uitbarstingen", "surges, eruptions (uitbarsting)"}, {"gevaarlijkste", "most dangerous (gevaarlijk)"}, {"bol", "orb, sphere"}, {"oproeper", "summoner"}, {"manascheur", "mana rift"}, {"benutten", "to harness, to make use of"}, {"voor korte tijd", "temporarily"}, {"scheur", "rift, tear"}, {"stromen", "to pour, to stream"}, {"verslaan", "to defeat"}, {"komt hun kracht vrij", "their power is released (vrijkomen)"}, {"toegestane", "allowed (toestaan)"}, {"getwijfeld", "doubted (twijfelen)"}, {"nauwelijks", "hardly, barely"}, {"Eerlijk waar", "honestly, really"} },
},

